/**
 * Fetches a Binary resource from a FHIR server and converts it into a Blob.
 * Handles both base64-encoded and raw binary formats.
 * @param {string} binaryRef - FHIR reference to the Binary resource (e.g. "Binary/123")
 * @param {object} fhirClient - Initialized SMART on FHIR client used to make requests
 * @returns {Promise<{ blob: Blob|null, deleted: boolean, reason?: string }>}
 */
async function fetchBinaryBlob(binaryRef, fhirClient) {
  console.log("Fetching binary blob for:", binaryRef);

  try {
    const binary = await fhirClient.request(binaryRef);

    // Case 1: Inline base64-encoded Binary (with `data`)
    if (binary.data) {
      try {
        const byteCharacters = atob(binary.data);
        const byteArray = new Uint8Array(
          [...byteCharacters].map((c) => c.charCodeAt(0))
        );
        const blob = new Blob([byteArray], { type: binary.contentType });

        return { blob, deleted: false };
      } catch (decodeError) {
        console.warn("Base64 decoding failed:", decodeError);
        throw new Error("Invalid base64 in Binary.data");
      }
    }

    // Case 2: Raw Binary resource — make direct request
    const response = await fetch(fhirClient.state.serverUrl + "/" + binaryRef, {
      headers: {
        Accept: binary.contentType || "application/octet-stream"
      }
    });

    if (!response.ok) throw new Error(`Failed to fetch raw binary: ${response.status}`);

    const blob = await response.blob();
    return { blob, deleted: false };
  } catch (error) {
    let diagnosticsText;

    const errorBody =
      error?.body ||
      error?.response?.body ||
      error?.response?.data;

    if (errorBody?.resourceType === "OperationOutcome") {
      diagnosticsText = errorBody.issue?.[0]?.diagnostics;
    }

    console.error("Error fetching binary:", error);

    return {
      blob: null,
      deleted: error?.statusCode === 410 || errorBody?.resourceType === "OperationOutcome",
      reason:
        diagnosticsText ||
        "Attachment fetch failed. Binary resource may have expired or been removed from the FHIR server."
    };
  }
}

module.exports = { fetchBinaryBlob };