import { createSlice } from "@reduxjs/toolkit";
import { decorateComms } from "../utils/decorateComms";

const initialState = {
  byId: {},
  threadMap: {},
  pendingIds: [],
  pageMap: {},
  currentPageUrl: null,
  newMessages: {
    byId: {},
    allIds: []
  }
};

// ─── SYNC UTILITY ─────────────────────────────────────────────────────────────
function syncNewMessagesWithById(state, msgId) {
  //console.log(`🔁 Syncing newMessages with byId for message ID: ${msgId}`);
  const updated = state.byId[msgId];
  if (state.newMessages.byId[msgId]) {
    state.newMessages.byId[msgId] = {
      ...state.newMessages.byId[msgId],
      ...updated,
      meta: {
        ...(state.newMessages.byId[msgId].meta || {}),
        ...(updated.meta || {})
      }
    };
  }
}

const messageSlice = createSlice({
  name: "messages",
  initialState,
  reducers: {
    addMessage: (state, action) => {
      // Extract the incoming message and its ID
      const msg = action.payload;
      const msgId = msg.id;

      // Retrieve the existing message if it exists, or default to an empty object
      const existing = state.byId[msgId] || {};

      // 🧱 Construct a new message object and assign it to state.byId[msgId]
      // - Creates a new object every time
      // - Merges incoming `msg` fields with existing ones
      // - Preserves `extension` if not provided in `msg`
      // - Deep-merges `meta` to retain enriched data or flags
      // - Adds `updatedAt` to track last update timestamp
      state.byId[msgId] = {
        id: msgId,
        ...msg, // spreads all top-level fields from the incoming message
        extension: msg.extension ?? existing.extension, // ✅ preserves existing extension if missing
        meta: {
          ...(existing.meta || {}), // 🧩 merge existing meta (e.g. enrichedData, flags)
          ...(msg.meta || {})       // 🧩 overwrite or add new meta fields from incoming message
        },
        updatedAt: new Date().toISOString() // 🕒 timestamp for last update
      };

      // 🧭 Determine the anchor ID for threading
      const anchorRef =
        msg.partOf?.[0]?.reference ||
        msg.inResponseTo?.[0]?.reference ||
        msg.id;
      const anchorId = anchorRef?.replace("Communication/", "") || msg.id;

      // 🧵 Initialize threadMap entry if it doesn't exist
      if (!state.threadMap[anchorId]) {
        state.threadMap[anchorId] = []; // 🆕 create new thread array
      }

      // 📌 Add message ID to threadMap if not already present
      if (!state.threadMap[anchorId].includes(msgId)) {
        state.threadMap[anchorId].push(msgId); // 🧩 mutate existing array
      }

      // ⏳ Track pending messages
      const isPending = msg.meta?.isPending;
      const isAlreadyTracked = state.pendingIds.includes(msgId);

      if (isPending && !isAlreadyTracked) {
        state.pendingIds.push(msgId); // 🧩 add to pending list
      } else if (!isPending && isAlreadyTracked) {
        state.pendingIds = state.pendingIds.filter(id => id !== msgId); // 🧹 remove from pending list
      }

      // 🔁 Sync newMessages if present (external utility)
      syncNewMessagesWithById(state, msgId);
    },

    setFullThread: (state, action) => {
      const { anchorId, messages } = action.payload;

      messages.forEach(msg => {
        state.byId[msg.id] = {
          ...(state.byId[msg.id] || {}),
          ...msg
        };
      });

      state.threadMap[anchorId] = messages.map(m => m.id);

      const confirmedIds = new Set(messages.map(m => m.id));
      state.pendingIds = state.pendingIds.filter(id => !confirmedIds.has(id));
    },



    setPageMessages: (state, action) => {
      console.log("*****************************************Setting page messages");
      const { pageUrl, messages, nextPageUrl, prevPageUrl, total } = action.payload;

      messages.forEach(msg => {
        const decorated = decorateComms(msg); // fill in missing fields
        const existing = state.byId[decorated.id] || {};

        state.byId[decorated.id] = {
          ...existing,
          ...decorated,
          meta: {
            ...existing.meta,
            ...decorated.meta
          }
        };
      });

      state.pageMap[pageUrl] = {
        ids: messages.map(msg => msg.id),
        nextPageUrl,
        prevPageUrl,
        total
      };

      const confirmedIds = new Set(messages.map(m => m.id));
      state.pendingIds = state.pendingIds.filter(id => !confirmedIds.has(id));
    },

    setCurrentPageUrl: (state, action) => {
      state.currentPageUrl = action.payload;
    },

    clearMessages: (state) => {
      state.byId = {};
      state.threadMap = {};
      state.pendingIds = [];
      state.pageMap = {};
      state.currentPageUrl = null;
      state.newMessages = { byId: {}, allIds: [] };
    },

    updateHydration: (state, action) => {
      const { id, enriched } = action.payload;
      const msg = state.byId[id];

      if (!msg) {
        console.info(`⚠️ Message with ID ${id} not found`);
        return;
      }

      state.byId[id] = {
        ...msg,
        meta: {
          ...(msg.meta || {}),
          hydrated: true,
          enrichedData: enriched,
          hydratedAt: new Date().toISOString()
        }
      };
    },

    addNewMessages: (state, action) => {
      const incoming = action.payload;

      incoming.forEach((msg) => {
        const msgId = msg.id;

        const alreadyInNew = !!state.newMessages.byId[msgId];
        const alreadyInMain = !!state.byId[msgId];

        if (!alreadyInNew) {
          state.newMessages.byId[msgId] = {
            ...msg,
            meta: {
              ...(msg.meta || {}),
              isPending: false,
              isNew: true
            }
          };
          state.newMessages.allIds.unshift(msgId);
        }

        if (!alreadyInMain) {
          state.byId[msgId] = {
            ...msg,
            meta: {
              ...(msg.meta || {}),
              isPending: false,
              isNew: true
            }
          };

          const anchorRef =
            msg.partOf?.[0]?.reference ||
            msg.inResponseTo?.[0]?.reference ||
            msg.id;
          const anchorId = anchorRef?.replace("Communication/", "") || msg.id;

          if (!state.threadMap[anchorId]) {
            state.threadMap[anchorId] = [];
          }
          if (!state.threadMap[anchorId].includes(msgId)) {
            state.threadMap[anchorId].push(msgId);
          }
        }
      });
    },

    clearNewMessages: (state) => {
      state.newMessages.byId = {};
      state.newMessages.allIds = [];
    },

    acknowledgeNewMessage: (state, action) => {
      const msgId = action.payload;
      if (state.newMessages.byId[msgId]) {
        delete state.newMessages.byId[msgId];
        state.newMessages.allIds = state.newMessages.allIds.filter(id => id !== msgId);
      }
    }
  }
});

export const {
  addMessage,
  setFullThread,
  setPageMessages,
  setCurrentPageUrl,
  clearMessages,
  updateHydration,
  addNewMessages,
  clearNewMessages,
  acknowledgeNewMessage
} = messageSlice.actions;

export default messageSlice.reducer;