import { createSlice } from "@reduxjs/toolkit";

const initialState = {
  orgConfig: null // Only one config expected
};

const configSlice = createSlice({
  name: "config",
  initialState,
  reducers: {
    setOrgConfig: (state, action) => {
      state.orgConfig = action.payload;
    },
    clearOrgConfig: (state) => {
      state.orgConfig = null;
    }
  }
});

export const { setOrgConfig, clearOrgConfig } = configSlice.actions;
export default configSlice.reducer;